<?php
require_once __DIR__.'/../common/config.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action'];try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM deposits WHERE id=? FOR UPDATE");$s->execute([$id]);$d=$s->fetch();if(!$d||$d['status']!=='Pending')throw new RuntimeException('Request is no longer pending.');if($action==='approve'){$pdo->prepare("UPDATE users SET wallet_balance=wallet_balance+? WHERE id=?")->execute([$d['amount'],$d['user_id']]);$pdo->prepare("INSERT INTO transactions(user_id,amount,type,description) VALUES(?,?, 'credit',?)")->execute([$d['user_id'],$d['amount'],'Deposit approved: '.$d['transaction_id']]);$status='Completed';}else{$status='Rejected';}$pdo->prepare("UPDATE deposits SET status=? WHERE id=?")->execute([$status,$id]);$pdo->commit();flash('success','Deposit request updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('deposit_requests.php');}
$rows=$pdo->query("SELECT d.*,u.username,u.email FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.created_at DESC")->fetchAll();$pageTitle='Deposit Requests';require __DIR__.'/common/header.php';
?>
<h1 class="text-2xl font-black mb-5">Deposit Requests</h1><div class="space-y-3"><?php foreach($rows as $r):?><div class="card rounded-2xl p-4"><div class="flex flex-wrap justify-between gap-3"><div><b><?=e($r['username'])?></b> · <?=money($r['amount'])?><div class="text-sm text-slate-400">Txn ID: <?=e($r['transaction_id'])?></div></div><span class="text-sm"><?=e($r['status'])?></span></div><?php if($r['status']==='Pending'):?><form method="post" class="flex gap-2 mt-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="approve" class="bg-emerald-600 rounded-xl px-4 py-2">Approve</button><button name="action" value="reject" class="bg-rose-600 rounded-xl px-4 py-2">Reject</button></form><?php endif;?></div><?php endforeach;?></div>
<?php require __DIR__.'/common/bottom.php'; ?>
